"use client";

/*
 * Slot animation model adapted from Danilaa1/slot-text.
 * Source: https://github.com/Danilaa1/slot-text
 * MIT License, Copyright (c) 2026 Daniel Belyi.
 */

import {
  createElement,
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  type HTMLAttributes,
} from "react";
import { cn } from "@/lib/utils";

type SlotTextDirection = "up" | "down";

interface SlotTextProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
  /** Text to render. Changing this value rolls the characters into place. */
  text: string;
  /** Roll direction. "down" enters from above, "up" enters from below. */
  direction?: SlotTextDirection;
  /** Delay between characters in milliseconds. */
  stagger?: number;
  /** Per-character animation duration in milliseconds. */
  duration?: number;
  /** Keep matching characters still when the text changes. */
  skipUnchanged?: boolean;
}

interface SlotTextOptions {
  direction?: SlotTextDirection;
  stagger?: number;
  duration?: number;
  skipUnchanged?: boolean;
}

interface ResolvedSlotTextOptions {
  direction: SlotTextDirection;
  stagger: number;
  duration: number;
  exitOffset: number;
  easing: string;
  bounce: number;
  skipUnchanged: boolean;
}

interface SlotState {
  timers: number[];
  target: string;
}

const DEFAULTS: ResolvedSlotTextOptions = {
  direction: "down",
  stagger: 45,
  duration: 300,
  exitOffset: 50,
  easing: "cubic-bezier(0.34, 1.56, 0.64, 1)",
  bounce: 0.6,
  skipUnchanged: true,
};

const NBSP = "\u00A0";
const states = new WeakMap<HTMLElement, SlotState>();

const containerClasses = "inline-flex whitespace-pre align-baseline";
const slotClasses = cn(
  "relative inline-flex flex-none justify-center overflow-hidden align-bottom leading-[1.3]",
  "[overflow-x:visible] [overflow-y:clip]",
);
const sizerClasses = "invisible whitespace-pre";
const faceClasses =
  "absolute inset-0 flex items-center justify-center whitespace-pre will-change-transform";

function glyph(char: string) {
  return char === " " ? NBSP : char;
}

function resolveOptions(options: SlotTextOptions = {}): ResolvedSlotTextOptions {
  return {
    direction: options.direction ?? DEFAULTS.direction,
    stagger: Math.max(0, options.stagger ?? DEFAULTS.stagger),
    duration: Math.max(0, options.duration ?? DEFAULTS.duration),
    exitOffset: DEFAULTS.exitOffset,
    easing: DEFAULTS.easing,
    bounce: DEFAULTS.bounce,
    skipUnchanged: options.skipUnchanged ?? DEFAULTS.skipUnchanged,
  };
}

function makeFace(char: string) {
  const face = document.createElement("span");
  face.className = faceClasses;
  face.dataset.slotTextFace = "";
  face.textContent = glyph(char);
  return face;
}

function buildSlot(char: string) {
  const slot = document.createElement("span");
  slot.className = slotClasses;
  slot.dataset.char = char;
  slot.setAttribute("aria-hidden", "true");

  const sizer = document.createElement("span");
  sizer.className = sizerClasses;
  sizer.dataset.slotTextSizer = "";
  sizer.textContent = glyph(char);

  slot.append(sizer, makeFace(char));
  return slot;
}

function buildSlotText(container: HTMLElement, text: string) {
  container.replaceChildren(...Array.from(text, buildSlot));
}

function settle(container: HTMLElement) {
  const state = states.get(container);
  if (!state) return;

  state.timers.forEach((timer) => window.clearTimeout(timer));
  states.delete(container);
  buildSlotText(container, state.target);
}

function wobble(index: number, salt: number) {
  const n = Math.sin((index + 1) * 12.9898 + salt * 78.233) * 43758.5453;
  return (n - Math.floor(n)) * 2 - 1;
}

function animateSlotText(container: HTMLElement, toText: string, options: SlotTextOptions = {}) {
  const { direction, stagger, duration, exitOffset, easing, bounce, skipUnchanged } =
    resolveOptions(options);

  settle(container);

  if (!container.querySelector("[data-char]")) {
    buildSlotText(container, toText);
    return;
  }

  const slots = Array.from(container.querySelectorAll<HTMLElement>("[data-char]"));
  const fromChars = slots.map((slot) => slot.dataset.char ?? "");
  const toChars = Array.from(toText);
  const fromText = fromChars.join("");

  if (fromText === toText) return;

  const maxLength = Math.max(fromChars.length, toChars.length);
  const sample = slots.find((slot) => (slot.dataset.char ?? "") !== "") ?? slots[0];
  const computedStyle = getComputedStyle(container);
  const height =
    Math.ceil(
      sample?.getBoundingClientRect().height ||
        sample?.offsetHeight ||
        container.getBoundingClientRect().height ||
        parseFloat(computedStyle.lineHeight) ||
        0,
    ) ||
    Math.ceil(parseFloat(computedStyle.fontSize) * 1.3) ||
    18;

  for (let index = slots.length; index < maxLength; index++) {
    const slot = buildSlot("");
    container.appendChild(slot);
    slots.push(slot);
    fromChars.push("");
  }

  const timers: number[] = [];
  const state: SlotState = { timers, target: toText };
  states.set(container, state);

  const outY = direction === "down" ? height : -height;
  const inStart = direction === "down" ? -height : height;
  let maxEnd = 0;

  for (let index = 0; index < maxLength; index++) {
    const fromChar = fromChars[index] ?? "";
    const toChar = toChars[index] ?? "";

    if (fromChar === toChar && (skipUnchanged || fromChar === "")) continue;

    const slot = slots[index];
    const sizer = slot.querySelector<HTMLElement>("[data-slot-text-sizer]")!;
    const oldFace = slot.querySelector<HTMLElement>("[data-slot-text-face]");

    const oldWidth = slot.getBoundingClientRect().width;
    sizer.textContent = glyph(toChar);
    const newWidth = sizer.getBoundingClientRect().width;
    const widthChanges = Math.abs(newWidth - oldWidth) > 0.5;

    if (widthChanges) slot.style.width = `${oldWidth}px`;
    if (fromChar === "" || toChar === "") slot.style.overflowX = "clip";

    const isTail = toChar === "";
    const characterDuration = Math.max(
      0,
      Math.round(duration * (isTail ? 0.75 : 1) * (1 + bounce * 0.45 * wobble(index, 1))),
    );
    const staggerIndex = isTail ? toChars.length * 0.5 + (index - toChars.length) * 0.25 : index;
    const baseDelay = Math.max(
      0,
      Math.round(staggerIndex * stagger * (1 + bounce * 0.25 * wobble(index, 2))),
    );
    const tilt = (bounce * 5 * wobble(index, 3)).toFixed(2);
    const rollTransition = `transform ${characterDuration}ms ${easing}`;

    const newFace = makeFace(toChar);
    newFace.style.transformOrigin = "50% 50%";
    newFace.style.transform = `translateY(${inStart}px) rotate(${tilt}deg)`;
    slot.appendChild(newFace);

    void slot.offsetWidth;

    if (widthChanges) {
      let widthDelay = baseDelay;
      let widthDuration = characterDuration;

      if (isTail) {
        widthDelay = baseDelay + Math.round(characterDuration * 0.55);
        widthDuration = Math.max(140, Math.round(characterDuration * 0.6));
      } else if (fromChar === "") {
        widthDuration = Math.max(140, Math.round(characterDuration * 0.45));
      }

      timers.push(
        window.setTimeout(() => {
          slot.style.transition = `width ${widthDuration}ms cubic-bezier(0.2, 0, 0, 1)`;
          slot.style.width = `${newWidth}px`;
        }, widthDelay),
      );
      maxEnd = Math.max(maxEnd, widthDelay + widthDuration);
    }

    maxEnd = Math.max(maxEnd, baseDelay + exitOffset + characterDuration);

    if (oldFace) {
      timers.push(
        window.setTimeout(() => {
          oldFace.style.transition = rollTransition;
          oldFace.style.transform = `translateY(${outY}px) rotate(${-Number(tilt)}deg)`;
        }, baseDelay),
      );
    }

    timers.push(
      window.setTimeout(() => {
        newFace.style.transition = rollTransition;
        newFace.style.transform = "translateY(0) rotate(0deg)";

        const done = (event: TransitionEvent) => {
          if (event.propertyName !== "transform") return;
          newFace.removeEventListener("transitionend", done);
          slot.dataset.char = toChar;
          slot.style.removeProperty("transition");
          slot.style.removeProperty("width");
          slot.style.removeProperty("overflow-x");
          slot.querySelectorAll("[data-slot-text-face]").forEach((face) => {
            if (face !== newFace) face.remove();
          });
        };

        newFace.addEventListener("transitionend", done);
      }, baseDelay + exitOffset),
    );
  }

  timers.push(
    window.setTimeout(() => {
      states.delete(container);
      buildSlotText(container, toText);
    }, maxEnd + 80),
  );
}

function clearSlotText(container: HTMLElement) {
  settle(container);
  container.textContent = "";
}

const SlotText = forwardRef<HTMLSpanElement, SlotTextProps>(
  (
    {
      text,
      direction = "down",
      stagger,
      duration,
      skipUnchanged,
      className,
      "aria-label": ariaLabel,
      ...props
    },
    forwardedRef,
  ) => {
    const elementRef = useRef<HTMLSpanElement>(null);
    const mountedRef = useRef(false);
    const firstTextEffectRef = useRef(true);
    const optionsRef = useRef<SlotTextOptions>({
      direction,
      stagger,
      duration,
      skipUnchanged,
    });

    useImperativeHandle(forwardedRef, () => elementRef.current!, []);

    useEffect(() => {
      optionsRef.current = { direction, stagger, duration, skipUnchanged };
    }, [direction, duration, skipUnchanged, stagger]);

    useEffect(() => {
      const element = elementRef.current;
      if (!element) return;

      buildSlotText(element, text);
      mountedRef.current = true;

      return () => {
        clearSlotText(element);
        mountedRef.current = false;
        firstTextEffectRef.current = true;
      };
    }, []);

    useEffect(() => {
      const element = elementRef.current;
      if (!element || !mountedRef.current) return;

      if (firstTextEffectRef.current) {
        firstTextEffectRef.current = false;
        return;
      }

      animateSlotText(element, text, optionsRef.current);
    }, [text]);

    return createElement("span", {
      ...props,
      "aria-label": ariaLabel ?? text,
      className: cn(containerClasses, className),
      ref: elementRef,
    });
  },
);

SlotText.displayName = "SlotText";

export { SlotText };
export type { SlotTextProps, SlotTextDirection };
